-- V5__freight_rate_observations.sql
-- Historical Freight Rate Observations (2024 - 2026)

CREATE TABLE IF NOT EXISTS freight_rate_observations (
    id BIGSERIAL PRIMARY KEY,
    route_id BIGINT REFERENCES routes(id),
    origin_region VARCHAR(100) NOT NULL,
    destination_port_id BIGINT REFERENCES ports(id),
    vessel_class_id BIGINT REFERENCES vessel_classes(id),
    cargo_type VARCHAR(50) NOT NULL DEFAULT 'dry-bulk',
    observation_date DATE NOT NULL,
    rate_usd_per_tonne DOUBLE PRECISION NOT NULL,
    bunker_price_usd_per_tonne DOUBLE PRECISION,
    congestion_index DOUBLE PRECISION,
    data_provenance VARCHAR(50) NOT NULL DEFAULT 'DATABASE',
    source VARCHAR(255) NOT NULL DEFAULT 'Baltic Exchange / Clarksons Dry Bulk Series',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_freight_obs_route_date ON freight_rate_observations(route_id, observation_date);
CREATE INDEX IF NOT EXISTS idx_freight_obs_origin_dest_date ON freight_rate_observations(origin_region, destination_port_id, observation_date);
CREATE INDEX IF NOT EXISTS idx_freight_obs_vessel_date ON freight_rate_observations(vessel_class_id, observation_date);

